#!/usr/bin/env python3
"""Targeted reviewed-plushie update. No collector/history/ledger writes."""
import argparse,ast,base64,hashlib,json,os,pwd,py_compile,shlex,shutil,sqlite3,subprocess,sys,tempfile,time,urllib.request
from pathlib import Path
PAYLOAD = {'services/reviewed_foundation.py': '', 'services/reviewed_stock_samples.py': '', 'services/monkey_combined.py': ''}
FOUNDATION_AST = 'd6070819639dbbc6970ca4a6650ebe9fb65511d44bb670a3eab6f3d636f8e5a1'
MONKEY_AST = 'a8d719722de9b5143db666267de5b5eacf2fe0249f95659b755a943cface257e'
COHORTS={'first-ten-beta':[('mex:Jaguar Plushie',1020)],'challengers-beta':[('can:Wolverine Plushie',1620),('cay:Stingray Plushie',1380),('arg:Monkey Plushie',6660),('sou:Lion Plushie',11820)],'next-six-beta':[('uae:Camel Plushie',10800)]}
POLICY='REVIEWED_STOCKED_SAMPLES_AND_PHASE_GUARDS_20261114_V1'
def semantic(text):return hashlib.sha256(ast.dump(ast.parse(text),include_attributes=False).encode()).hexdigest()
def patch_schedule(text):
    replacements=[('from services.reviewed_foundation import REVIEWED,calculate,sa_forecast','from services.reviewed_foundation import REVIEWED,calculate,sa_forecast,camel_forecast,BASE_REVIEWED,BASE_POLICY'),('SELECT received_epoch,country_update_epoch,clock_status FROM country_stock_observations','SELECT received_epoch,source,country_update_epoch,clock_status FROM country_stock_observations'),("        if item_key=='sou:Xanax':event_forecaster=sa_forecast","        if item_key=='sou:Xanax':event_forecaster=sa_forecast\n        if item_key=='uae:Camel Plushie':event_forecaster=camel_forecast"),('timing_choice=lambda **kw: native_timing_choice(source','timing_choice=None if item_key in {"uae:Camel Plushie","sou:Lion Plushie"} else lambda **kw: native_timing_choice(source')]
    for before,after in replacements:
        if text.count(before)!=1:raise ValueError('Unrecognized installed scheduling source; no changes applied')
        text=text.replace(before,after)
    anchor='    decision = build_first_release_decision(\n        forecast, now=now'
    if text.count(anchor)!=1:raise ValueError('Unrecognized decision hook; no changes applied')
    text=text.replace(anchor,"    if item_key in BASE_REVIEWED:\n        forecast['reviewed_base_policy']=BASE_POLICY\n        if phases.get('withhold_new_advice'):\n            forecast=dict(forecast,restock_events=[],current_stock_window=None,status='PHASE_CONFIRMATION_PENDING')\n    decision = build_first_release_decision(\n        forecast, now=now")
    compile(text,'installed-schedule','exec');return text

def cmd(args,**kw):
    try:return subprocess.run(args,text=True,capture_output=True,check=True,**kw)
    except subprocess.CalledProcessError as error:
        print(json.dumps({'status':'COMMAND_FAILED','executable':str(args[0]),'exit_code':error.returncode,'stderr':(error.stderr or '')[-12000:],'stdout':(error.stdout or '')[-4000:]}),flush=True)
        raise

def stage_directory():
    # Ubuntu must traverse this path independently of private root backup
    # ancestors and sudo's umask. Keep rollback data out of this directory.
    stage=Path(tempfile.mkdtemp(prefix='torn-fren-reviewed-stage-',dir='/tmp'))
    stage.chmod(0o755)
    return stage

def stage_cohort(parent,cohort):
    stage=parent/cohort;stage.mkdir(mode=0o755);stage.chmod(0o755)
    return stage
def replay_environment(unit):
    # The real services disable the legacy private-research override. A bare
    # sudo/runuser process does not inherit systemd's Environment settings.
    values=dict(entry.split('=',1) for entry in shlex.split(show(unit,'Environment')) if '=' in entry)
    names=('TORNFREN_REPLAY_PINNED_RESEARCH','TORNFREN_REPLAY_WORK')
    if not values.get(names[0]):
        raise ValueError('Publisher replay environment is not configured; no changes applied: '+unit)
    return [name+'='+values[name] for name in names if name in values]

def state(unit):return cmd(['systemctl','show',unit,'--value','-p','ActiveState']).stdout.strip()
def show(unit,field):return cmd(['systemctl','show',unit,'--value','-p',field]).stdout.strip()
def atomic(path,data,mode=0o644):
    fd,tmp=tempfile.mkstemp(prefix='.base-update-',dir=path.parent)
    try:
        with os.fdopen(fd,'wb')as f:f.write(data);f.flush();os.fsync(f.fileno())
        os.chmod(tmp,mode);os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):os.unlink(tmp)

def verify_public():
    with urllib.request.urlopen('http://127.0.0.1:8000/api/first-release',timeout=30)as r:board=json.load(r)
    rows={r['item_key']:r for r in board.get('rows',[])}
    if len(rows)!=24:raise ValueError('Public feed roster verification failed')
    for items in COHORTS.values():
        for key,_ in items:
            row=rows.get(key,{})
            if (row.get('forecast')or{}).get('reviewed_base_policy')!=POLICY or row.get('valid_until_epoch',0)<time.time():
                raise ValueError('Fresh public policy is not available for '+key)
    return True

def apply():
    if os.geteuid()!=0:raise SystemExit('Run with sudo -n python3 - --apply')
    python=Path('/home/ubuntu/torn-fren-v38-probe/.venv/bin/python')
    if not python.is_file():raise ValueError('Expected publisher Python is unavailable; no changes applied')
    payload={k:base64.b64decode(v)for k,v in PAYLOAD.items()};plans=[];timers={};replay_env={};backup=None;installed=False;already=[]
    for cohort in COHORTS:
        unit='torn-fren-'+cohort+'.service';root=Path(show(unit,'WorkingDirectory'))
        if not root.is_absolute()or root.is_symlink()or not str(root.resolve()).startswith('/var/lib/torn-fren-live-beta/releases/'):
            raise ValueError('Unexpected publisher working directory; no changes applied')
        f=root/'services/reviewed_foundation.py';schedule=root/'services/first_release_schedule.py'
        if f.is_symlink()or schedule.is_symlink():raise ValueError('Unexpected source link; no changes applied')
        if semantic(f.read_text())==semantic(payload['services/reviewed_foundation.py'].decode()):
            expected={root/rel:data for rel,data in payload.items()if rel!='services/monkey_combined.py'or cohort=='challengers-beta'}
            if not all(path.is_file()and path.read_bytes()==data for path,data in expected.items())or 'reviewed_base_policy'not in schedule.read_text():
                raise ValueError('Mixed installed update; no changes applied')
            already.append(cohort);continue
        if semantic(f.read_text())!=FOUNDATION_AST:
            raise ValueError('Installed foundation differs from the reviewed base; no changes applied')
        changes={root/rel:data for rel,data in payload.items()if rel!='services/monkey_combined.py'or cohort=='challengers-beta'}
        changes[schedule]=patch_schedule(schedule.read_text()).encode()
        if cohort=='challengers-beta'and semantic((root/'services/monkey_combined.py').read_text())!=MONKEY_AST:
            raise ValueError('Installed Monkey model differs from the reviewed base; no changes applied')
        replay_env[cohort]=replay_environment(unit)
        plans.append((cohort,root,changes));timers['torn-fren-'+cohort+'.timer']=state('torn-fren-'+cohort+'.timer')=='active'
    if already:
        if len(already)!=len(COHORTS):raise ValueError('Mixed publisher revisions; no changes applied')
        verify_public();print(json.dumps({'status':'ALREADY_INSTALLED_AND_FRESH','items':6}));return
    # Stage CLI inference with injected modules; no installed source is changed.
    parent=Path('/var/backups/torn-fren-ops');parent.mkdir(exist_ok=True)
    backup=Path(tempfile.mkdtemp(prefix='reviewed-base-six-',dir=parent));backup.chmod(0o700)
    staging=stage_directory()
    saved=[];snapshot=staging/'stage-input.sqlite'
    try:
        collector=Path('/opt/torn-fren/data/stock_history.db').resolve()
        with sqlite3.connect(collector.as_uri()+'?mode=ro',uri=True)as original,sqlite3.connect(snapshot)as frozen:
            original.backup(frozen)
            issued=max(frozen.execute('SELECT MAX(timestamp) FROM poll_heartbeats WHERE success=1').fetchone()[0]or 0,frozen.execute('SELECT MAX(timestamp) FROM stock_history').fetchone()[0]or 0)
        if not 0<=time.time()-issued<=180:raise ValueError('Collector is not fresh; installed source remains unchanged')
        ubuntu=pwd.getpwnam('ubuntu');os.chown(snapshot,ubuntu.pw_uid,ubuntu.pw_gid);snapshot.chmod(0o400)
        for cohort,root,changes in plans:
            stage=stage_cohort(staging,cohort)
            for target,data in changes.items():
                dst=stage/target.name;dst.write_bytes(data);dst.chmod(0o644);py_compile.compile(str(dst),doraise=True)
                saved.append({'path':str(target),'previous':base64.b64encode(target.read_bytes()).decode()if target.exists()else None,'mode':target.stat().st_mode&0o777 if target.exists()else 0o644,'new_sha256':hashlib.sha256(data).hexdigest()})
            shim=stage/'stage.py'
            shim.write_text("import importlib.util,sys,os,runpy\nsys.path.insert(0,os.getcwd())\nimport services\n"+"\n".join("spec=importlib.util.spec_from_file_location('services.'+"+repr(name)+", "+repr(str(stage/(name+'.py')))+");m=importlib.util.module_from_spec(spec);sys.modules[spec.name]=m;setattr(services,"+repr(name)+",m);spec.loader.exec_module(m)"for name in ('reviewed_stock_samples','reviewed_foundation')+(('monkey_combined',)if cohort=='challengers-beta'else())+('first_release_schedule',))+"\nrunpy.run_module('services.first_release_live',run_name='__main__')\n")
            shim.chmod(0o644)
            source=snapshot
            flags=[]if cohort=='first-ten-beta'else['--challenger-cohort']if cohort=='challengers-beta'else['--next-six-cohort']
            for key,flight in COHORTS[cohort]:
                r=cmd(['runuser','-u','ubuntu','--','env','OPENBLAS_NUM_THREADS=1','OMP_NUM_THREADS=1','MKL_NUM_THREADS=1',*replay_env[cohort],str(python),'-B',str(shim),'item','--source',str(source),'--key',key,'--issued',str(issued),'--flight',str(flight),*flags],cwd=root,timeout=180)
                value=json.loads(r.stdout);forecast=value.get('forecast')or{}
                if forecast.get('reviewed_base_policy')!=POLICY:raise ValueError('Staged item did not execute the reviewed policy: '+key)
                print(json.dumps({'status':'STAGED_ITEM_VERIFIED','item':key}),flush=True)
        (backup/'rollback.json').write_text(json.dumps(saved))
        # Pause schedules, let each current worker finish, then replace only
        # reviewed source files. No SQLite database is replaced or vacuumed.
        for timer,active in timers.items():
            if active:cmd(['systemctl','stop',timer])
        deadline=time.monotonic()+240
        for cohort,root,changes in plans:
            unit='torn-fren-'+cohort+'.service'
            while state(unit)in('active','activating','deactivating'):
                if time.monotonic()>deadline:raise TimeoutError('Publisher still busy; no cutover performed')
                time.sleep(1)
        installed=True
        for cohort,root,changes in plans:
            for target,data in changes.items():atomic(target,data,target.stat().st_mode&0o777 if target.exists()else 0o644)
        for cohort,root,changes in plans:
            cmd(['systemctl','start','torn-fren-'+cohort+'.service'],timeout=200)
        for timer,active in timers.items():
            if active:cmd(['systemctl','start',timer])
        deadline=time.monotonic()+240
        while True:
            try:
                verify_public();break
            except (OSError,ValueError):
                if time.monotonic()>deadline:raise
                time.sleep(3)
        print(json.dumps({'status':'SIX_ITEM_UPDATE_VERIFIED','items':6,'backup':str(backup),'historical_records_deleted':False,'unresolved_predictions_deleted':False}),flush=True)
    except Exception:
        if installed:
            for timer in timers:subprocess.run(['systemctl','stop',timer],check=False)
            for cohort,_,_ in plans:subprocess.run(['systemctl','stop','torn-fren-'+cohort+'.service'],check=False)
            for entry in saved:
                path=Path(entry['path'])
                if entry['previous']is None:
                    if path.exists()and hashlib.sha256(path.read_bytes()).hexdigest()==entry['new_sha256']:path.unlink()
                else:atomic(path,base64.b64decode(entry['previous']),entry['mode'])
            print(json.dumps({'status':'ORIGINAL_SOURCE_RESTORED','backup':str(backup),'database_records_restored_or_deleted':False}),flush=True)
        raise
    finally:
        shutil.rmtree(staging)
        for timer,active in timers.items():
            if active:subprocess.run(['systemctl','start',timer],check=False)

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--apply',action='store_true');a=parser.parse_args()
    if not a.apply:raise SystemExit('Use --apply after reviewing the six-item update.')
    apply()
